import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Trash Bin Pro for Pterodactyl — quotas, retention, restores, purge behavior, sub-user permissions, and compatibility.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Trash Bin Pro for Pterodactyl — quotas, retention, restores, purge behavior, sub-user permissions, and compatibility."},"headers":[],"relativePath":"trash-bin-pro/getting-started/faq.md","filePath":"trash-bin-pro/getting-started/faq.md","lastUpdated":null}'),i={name:"trash-bin-pro/getting-started/faq.md"};function n(o,e,h,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="quotas-disk-usage" tabindex="-1">Quotas &amp; Disk Usage <a class="header-anchor" href="#quotas-disk-usage" aria-label="Permalink to &quot;Quotas &amp; Disk Usage&quot;">​</a></h2><h3 id="does-the-trash-bin-count-against-the-server-s-disk-quota" tabindex="-1">Does the Trash Bin count against the server&#39;s disk quota? <a class="header-anchor" href="#does-the-trash-bin-count-against-the-server-s-disk-quota" aria-label="Permalink to &quot;Does the Trash Bin count against the server&#39;s disk quota?&quot;">​</a></h3><p>Yes. Trashed files are real files living in <code>/.trash</code> on the game server&#39;s filesystem — they keep consuming the container&#39;s disk allocation until they are restored, purged, or the Trash is emptied. Use the capacity limits in the admin panel (global default, per-egg, or per-server override) to keep trash usage bounded; the default is <code>0</code> (unlimited), so set a cap if disk abuse is a concern.</p><h3 id="what-happens-when-the-trash-bin-is-full" tabindex="-1">What happens when the Trash Bin is full? <a class="header-anchor" href="#what-happens-when-the-trash-bin-is-full" aria-label="Permalink to &quot;What happens when the Trash Bin is full?&quot;">​</a></h3><p>The move-to-trash is refused: the API returns HTTP <code>409</code> with a <code>TrashBinFull</code> error, and the file manager shows a &quot;Trash Bin is full — empty it and retry&quot; banner. The delete is blocked entirely — the file is <strong>not</strong> hard-deleted as a fallback and stays where it is until the Trash is emptied or enough of it expires.</p><h3 id="what-if-a-single-file-is-bigger-than-the-trash-capacity" tabindex="-1">What if a single file is bigger than the Trash capacity? <a class="header-anchor" href="#what-if-a-single-file-is-bigger-than-the-trash-capacity" aria-label="Permalink to &quot;What if a single file is bigger than the Trash capacity?&quot;">​</a></h3><p>The user gets a <strong>Delete Permanently</strong> dialog instead: the file manager explains the file exceeds the Trash Bin capacity and offers a permanent delete guarded by a required acknowledgement checkbox (the danger button stays disabled until it is ticked). Confirming sends the delete with <code>permanent: true</code>, bypassing the Trash Bin entirely. Cancelling leaves the file untouched.</p><h2 id="retention-purging" tabindex="-1">Retention &amp; Purging <a class="header-anchor" href="#retention-purging" aria-label="Permalink to &quot;Retention &amp; Purging&quot;">​</a></h2><h3 id="what-do-0-and-the-retention-limits-actually-mean" tabindex="-1">What do &quot;0&quot; and the retention limits actually mean? <a class="header-anchor" href="#what-do-0-and-the-retention-limits-actually-mean" aria-label="Permalink to &quot;What do &quot;0&quot; and the retention limits actually mean?&quot;">​</a></h3><p>Capacity and retention have different zero semantics:</p><ul><li><strong>Capacity (<code>max_bytes</code>)</strong>: <code>0</code> means <strong>unlimited</strong> — the Trash Bin can grow without bound (still bounded by the server&#39;s real disk).</li><li><strong>Retention (<code>retention_hours</code>)</strong>: minimum is <strong>1 hour</strong>, maximum <code>8760</code> (one year). There is no &quot;keep forever&quot; — everything in the Trash is eventually purged. The global default is 24 hours.</li></ul><p>Effective values resolve per server as: server override → egg override → global default.</p><h3 id="does-empty-trash-bypass-the-retention-window" tabindex="-1">Does Empty Trash bypass the retention window? <a class="header-anchor" href="#does-empty-trash-bypass-the-retention-window" aria-label="Permalink to &quot;Does Empty Trash bypass the retention window?&quot;">​</a></h3><p>Yes. <strong>Empty Trash</strong> permanently deletes everything immediately, regardless of how recently it was trashed. It is a hard delete through Wings — the files are not recoverable afterwards.</p><h3 id="what-if-wings-is-down-when-the-hourly-purge-runs" tabindex="-1">What if Wings is down when the hourly purge runs? <a class="header-anchor" href="#what-if-wings-is-down-when-the-hourly-purge-runs" aria-label="Permalink to &quot;What if Wings is down when the hourly purge runs?&quot;">​</a></h3><p>The purge is fault-tolerant and per-server. If a Wings node is unreachable, that server&#39;s rows are <strong>left in the database</strong> and retried on the next hourly run — one failed server never blocks the others. A warning is logged (<code>storage/logs/laravel.log</code>) and the command reports how many servers will be retried. Note the inverse is also safe: if files were already deleted on Wings but the DB rows survived, the restore/permanent-delete paths clean up those ghost rows instead of erroring.</p><h3 id="what-happens-if-the-server-itself-is-deleted" tabindex="-1">What happens if the server itself is deleted? <a class="header-anchor" href="#what-happens-if-the-server-itself-is-deleted" aria-label="Permalink to &quot;What happens if the server itself is deleted?&quot;">​</a></h3><p>Two layers handle it. The <code>server_id</code> foreign key cascades, so trash rows are normally removed with the server. Any row that outlives its server is picked up as an orphan by the next purge run and its DB record is dropped — no Wings call is attempted for a server that no longer exists.</p><h2 id="restores" tabindex="-1">Restores <a class="header-anchor" href="#restores" aria-label="Permalink to &quot;Restores&quot;">​</a></h2><h3 id="what-happens-if-a-file-with-the-same-name-already-exists-at-the-restore-location" tabindex="-1">What happens if a file with the same name already exists at the restore location? <a class="header-anchor" href="#what-happens-if-a-file-with-the-same-name-already-exists-at-the-restore-location" aria-label="Permalink to &quot;What happens if a file with the same name already exists at the restore location?&quot;">​</a></h3><p>Restores are collision-safe. If the original path is taken, the file is restored as <code>name (restored)</code>; if that is taken too, <code>name (restored 2)</code>, and so on. The original file at that path is never overwritten.</p><h3 id="can-sub-users-use-the-trash-bin" tabindex="-1">Can sub-users use the Trash Bin? <a class="header-anchor" href="#can-sub-users-use-the-trash-bin" aria-label="Permalink to &quot;Can sub-users use the Trash Bin?&quot;">​</a></h3><p>Yes, if they have the <strong>trashbinpro.access</strong> permission (granted on the sub-user management page). It governs viewing the Trash, restoring, deleting from Trash, and Empty Trash, and is enforced server-side on every endpoint — the restore request class authorizes <code>trashbinpro.access</code> independently. The regular <code>file.delete</code> permission still controls whether they can delete (and therefore trash) files in the first place. Sub-users without <code>trashbinpro.access</code> get a <code>403</code> on the Trash view.</p><h2 id="operation-compatibility" tabindex="-1">Operation &amp; Compatibility <a class="header-anchor" href="#operation-compatibility" aria-label="Permalink to &quot;Operation &amp; Compatibility&quot;">​</a></h2><h3 id="can-i-disable-trash-bin-pro-without-uninstalling-it" tabindex="-1">Can I disable Trash Bin Pro without uninstalling it? <a class="header-anchor" href="#can-i-disable-trash-bin-pro-without-uninstalling-it" aria-label="Permalink to &quot;Can I disable Trash Bin Pro without uninstalling it?&quot;">​</a></h3><p>Yes — set <strong>enabled</strong> to off in <strong>Admin → Trash Bin Pro</strong>. When disabled, deletes fall back to the stock panel behavior (immediate permanent delete) and the Trash UI no longer intercepts anything. Files already in the Trash are untouched and the hourly purge keeps running, so existing trash still expires on schedule.</p><h3 id="where-is-trash-activity-logged" tabindex="-1">Where is trash activity logged? <a class="header-anchor" href="#where-is-trash-activity-logged" aria-label="Permalink to &quot;Where is trash activity logged?&quot;">​</a></h3><p>In Pterodactyl&#39;s built-in activity log, visible on the server&#39;s Activity page. Every operation writes an event: <code>server:trashbinpro.trash</code>, <code>server:trashbinpro.restore</code>, <code>server:trashbinpro.purge</code> (permanent delete from Trash), and <code>server:trashbinpro.empty</code>. Logging can be turned off with the <code>logging_enabled</code> setting in the admin panel.</p><h3 id="does-it-work-with-themes-and-modified-panels" tabindex="-1">Does it work with themes and modified panels? <a class="header-anchor" href="#does-it-work-with-themes-and-modified-panels" aria-label="Permalink to &quot;Does it work with themes and modified panels?&quot;">​</a></h3><p>It is built for them. The PHP and SPA patchers are marker-guarded and idempotent (safe to re-run, zero-diff no-ops when already applied), and the frontend import patches are <strong>anchor-free</strong> — they merge into existing import statements instead of searching for exact stock code lines, which is what broke on theme-modified panels in v1.0.0 (<code>faTrash is not defined</code>). If a patch genuinely cannot find its place, the patcher fails loudly and exits non-zero rather than leaving a half-patched file — see the <a href="./installation#troubleshooting">troubleshooting table</a>.</p><h3 id="which-pterodactyl-and-blueprint-versions-are-supported" tabindex="-1">Which Pterodactyl and Blueprint versions are supported? <a class="header-anchor" href="#which-pterodactyl-and-blueprint-versions-are-supported" aria-label="Permalink to &quot;Which Pterodactyl and Blueprint versions are supported?&quot;">​</a></h3><p>Pterodactyl Panel <strong>v1.11.x / v1.12.x</strong> (Laravel 11, PHP 8.2+), and Blueprint <code>beta-2026-05</code> for the Blueprint package. The standalone installer has no Blueprint dependency. See <a href="./installation">Installation</a> for the full prerequisite list.</p>',33)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
